// Prepend the "generated" header with the spec's sha256 to a generated file (SDK.md §3.4).
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";

const file = process.argv[2];
const spec = readFileSync(new URL("../../openapi/onemind-v1.json", import.meta.url));
const sha = createHash("sha256").update(spec).digest("hex");
const body = readFileSync(file, "utf8").replace(/^\/\/ Code generated[^\n]*\n(\/\/ SPDX[^\n]*\n)?\/\/ Spec sha256[^\n]*\n/, "");
writeFileSync(
  file,
  `// Code generated by openapi-typescript 7.13.0 from sdk/openapi/onemind-v1.json. DO NOT EDIT.\n// SPDX-License-Identifier: Apache-2.0\n// Spec sha256: ${sha}\n${body}`,
);
